/**
 * Escape plain text for safe insertion into HTML (text nodes and quoted attributes).
 * Stored values stay raw; call this only when building markup strings.
 */
export function escapeHtml(raw: string): string {
  return raw
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
